LOGIN_HTML = '<!DOCTYPE html>\n<html lang="en">\n<head>\n<meta charset="UTF-8">\n<meta name="viewport" content="width=device-width, initial-scale=1.0">\n<title>RMGC · Agronomy</title>\n<link href="https://fonts.googleapis.com/css2?family=Playfair+Display:wght@600&family=DM+Sans:wght@300;400;500&display=swap" rel="stylesheet">\n<style>\n*{margin:0;padding:0;box-sizing:border-box}\nbody{min-height:100vh;background:#0d1f0d;display:flex;align-items:center;justify-content:center;font-family:\'DM Sans\',sans-serif;\n  background-image:radial-gradient(ellipse at 20% 50%,rgba(34,85,34,0.3) 0%,transparent 60%),\n                   radial-gradient(ellipse at 80% 20%,rgba(20,60,20,0.4) 0%,transparent 50%)}\n.card{background:rgba(255,255,255,0.04);border:1px solid rgba(255,255,255,0.08);border-radius:16px;padding:48px 40px;width:360px;backdrop-filter:blur(20px)}\n.logo{text-align:center;margin-bottom:32px}\n.logo-crest{width:56px;height:56px;background:linear-gradient(135deg,#2d6a2d,#4a9e4a);border-radius:50%;display:flex;align-items:center;justify-content:center;margin:0 auto 12px;font-size:24px}\n.logo h1{font-family:\'Playfair Display\',serif;color:#e8f5e8;font-size:22px;letter-spacing:0.5px}\n.logo p{color:#6a9e6a;font-size:12px;letter-spacing:2px;text-transform:uppercase;margin-top:4px}\nlabel{display:block;color:#9ab89a;font-size:12px;letter-spacing:1px;text-transform:uppercase;margin-bottom:6px;margin-top:20px}\ninput{width:100%;background:rgba(255,255,255,0.06);border:1px solid rgba(255,255,255,0.1);border-radius:8px;padding:12px 14px;color:#e8f5e8;font-size:14px;font-family:\'DM Sans\',sans-serif;outline:none;transition:border-color 0.2s}\ninput:focus{border-color:#4a9e4a}\n.btn{width:100%;margin-top:28px;padding:13px;background:linear-gradient(135deg,#2d6a2d,#3d8a3d);border:none;border-radius:8px;color:#e8f5e8;font-size:14px;font-weight:500;letter-spacing:0.5px;cursor:pointer;font-family:\'DM Sans\',sans-serif;transition:opacity 0.2s}\n.btn:hover{opacity:0.85}\n.error{color:#e57373;font-size:13px;margin-top:16px;text-align:center;background:rgba(229,115,115,0.1);padding:8px;border-radius:6px}\n</style>\n</head>\n<body>\n<div class="card">\n  <div class="logo">\n    <div class="logo-crest">⛳</div>\n    <h1>RMGC Agronomy</h1>\n    <p>Schedule &amp; KPIs</p>\n  </div>\n  <form method="POST" action="/login">\n    <label>Username</label>\n    <input type="text" name="username" autocomplete="username" autofocus required>\n    <label>Password</label>\n    <input type="password" name="password" autocomplete="current-password" required>\n    <button class="btn" type="submit">Sign In</button>\n    {% if error %}<div class="error">{{ error }}</div>{% endif %}\n  </form>\n</div>\n</body>\n</html>\n'

INDEX_HTML = '<!DOCTYPE html>\n<html lang="en">\n<head>\n<meta charset="UTF-8">\n<meta name="viewport" content="width=device-width, initial-scale=1.0">\n<title>RMGC · Schedule & KPIs 2026</title>\n<link href="https://fonts.googleapis.com/css2?family=Playfair+Display:wght@600;700&family=DM+Sans:wght@300;400;500;600&display=swap" rel="stylesheet">\n<style>\n*{margin:0;padding:0;box-sizing:border-box}\n:root{\n  --gd:#1a4731;--gm:#2d6a4f;--gl:#A8D5BA;--bg:#f4f7f4;\n  --g400:#6b7c6b;--g200:#e8f0e8;--g100:#f0f5f0;\n  --amber:#d97706;--red:#dc2626;--blue:#1e40af;--teal:#0b6b5a;\n  --border:#dde8dd;--text:#1a2e1a;--muted:#6b7c6b;\n}\nbody{background:var(--bg);color:var(--text);font-family:\'DM Sans\',sans-serif;min-height:100vh}\n\n/* ── Topbar ── */\n.topbar{background:var(--gd);border-bottom:2px solid var(--gm);position:sticky;top:0;z-index:100;\n  display:flex;align-items:center;padding:0 20px;height:54px;gap:12px}\n.brand{display:flex;align-items:center;gap:9px;flex:1;min-width:0}\n.brand-icon{font-size:20px}\n.brand-name{font-family:\'Playfair Display\',serif;font-size:17px;color:#fff;white-space:nowrap}\n.brand-sub{font-size:11px;color:#A8D5BA;letter-spacing:1px}\n.tabs{display:flex;gap:3px}\n.tab{padding:7px 18px;border-radius:6px;border:1px solid transparent;background:transparent;\n  color:rgba(255,255,255,0.65);font-family:\'DM Sans\',sans-serif;font-size:13px;font-weight:500;\n  cursor:pointer;transition:all 0.18s}\n.tab.active{background:rgba(255,255,255,0.15);border-color:rgba(255,255,255,0.2);color:#fff}\n.tab:hover:not(.active){color:#fff;background:rgba(255,255,255,0.08)}\n.topbar-right{display:flex;align-items:center;gap:10px;flex-shrink:0}\n.sync-dot{width:7px;height:7px;border-radius:50%;background:rgba(255,255,255,0.3);transition:background 0.3s}\n.sync-dot.synced{background:#A8D5BA}\n.sync-dot.syncing{background:#fbbf24;animation:pulse 1s infinite}\n@keyframes pulse{0%,100%{opacity:1}50%{opacity:0.4}}\n.user-badge{font-size:11.5px;color:rgba(255,255,255,0.7);padding:3px 10px;\n  background:rgba(255,255,255,0.1);border:1px solid rgba(255,255,255,0.15);border-radius:20px;white-space:nowrap}\n.user-badge span{color:#A8D5BA;font-weight:600}\n.logout-btn{font-size:12px;color:rgba(255,255,255,0.55);background:none;border:none;cursor:pointer;\n  font-family:\'DM Sans\',sans-serif;text-decoration:underline}\n.logout-btn:hover{color:#fff}\n\n/* ── Main ── */\n.main{padding:22px 18px;max-width:1400px;margin:0 auto}\n.page{display:none}.page.active{display:block}\n\n/* ── Section header ── */\n.sec-header{display:flex;align-items:center;justify-content:space-between;margin-bottom:12px;flex-wrap:wrap;gap:8px}\n.sec-title{font-family:\'Playfair Display\',serif;font-size:20px;color:var(--gd)}\n.sec-stats{font-size:13px;color:var(--muted)}\n.sec-stats strong{color:var(--gd);font-weight:700}\n\n/* ── Progress ── */\n.prog-wrap{margin-bottom:18px}\n.prog-track{height:6px;background:#dde8dd;border-radius:3px;overflow:hidden}\n.prog-fill{height:100%;background:linear-gradient(90deg,var(--gm),#4ade80);border-radius:3px;transition:width 0.4s}\n\n/* ── Gantt table ── */\n.gantt-outer{overflow-x:auto;border-radius:10px;border:1px solid var(--border);background:#fff;box-shadow:0 1px 4px rgba(0,0,0,0.06)}\n.gantt-table{width:100%;border-collapse:collapse;min-width:800px}\n.gantt-table thead th{background:var(--gd);color:#A8D5BA;font-weight:600;\n  font-size:11px;letter-spacing:0.8px;text-transform:uppercase;padding:9px 5px;text-align:center;\n  border-right:1px solid rgba(255,255,255,0.08)}\n.gantt-table thead th.name-col{text-align:left;padding-left:14px;min-width:200px;max-width:240px;color:#fff}\n/* category separator */\ntr.cat-sep td{padding:5px 14px;font-size:10.5px;letter-spacing:1.2px;text-transform:uppercase;\n  font-weight:700;border-bottom:1px solid var(--border)}\n/* data rows */\n.gantt-table tbody tr.data-row{border-bottom:1px solid #f0f5f0}\n.gantt-table tbody tr.data-row:hover td{background:#eef5ee}\n.name-td{padding:7px 8px 7px 14px;font-size:12.5px;color:var(--text);vertical-align:middle;line-height:1.35;\n  border-right:1px solid var(--border)}\n.name-td .kn{font-size:10.5px;color:var(--muted);margin-right:5px;font-weight:600}\n/* month cell */\n.month-td{padding:3px 2px;text-align:center;vertical-align:middle;border-right:1px solid rgba(0,0,0,0.08)}\n.month-td.inactive{background:#fff}\n\n/* ── Tick button ── */\n.tick-wrap{display:flex;flex-direction:column;align-items:center;gap:3px;padding:2px}\n.tick-btn{width:26px;height:26px;border-radius:5px;border:2px solid rgba(0,0,0,0.28);\n  background:rgba(255,255,255,0.92);cursor:pointer;display:flex;align-items:center;justify-content:center;\n  transition:all 0.13s;font-size:0}\n.tick-btn:hover:not(:disabled){border-color:var(--gm);background:#f0faf0}\n.tick-btn.ticked{background:var(--gd);border-color:var(--gd)}\n.tick-btn.ticked::after{content:\'✓\';color:#fff;font-size:13px;font-weight:700}\n.tick-btn:disabled{cursor:default;opacity:0.75}\n.note-dot{width:8px;height:8px;border-radius:50%;background:#aaa;opacity:0.35;transition:all 0.2s;cursor:pointer;border:1px solid rgba(0,0,0,0.15)}\n.note-dot.vis{opacity:1;transform:scale(1.2);background:#e8564a;border-color:#b03020}\n\n/* ── Note drawer ── */\n.note-row{display:none}\n.note-row.open{display:table-row}\n.note-row td{padding:0 8px 8px 14px;background:#fffbf0;border-bottom:1px solid #fde68a}\n.note-inner{border:1px solid #fde68a;border-radius:6px;padding:7px 10px;display:flex;gap:8px;align-items:flex-start;flex-wrap:wrap}\n.note-label{font-size:10.5px;color:var(--amber);font-weight:700;white-space:nowrap;padding-top:4px}\n.note-ta{flex:1;min-width:200px;background:#fff;border:1px solid #fde68a;\n  border-radius:4px;padding:5px 8px;color:var(--text);font-family:\'DM Sans\',sans-serif;font-size:12px;\n  resize:vertical;outline:none;min-height:44px;line-height:1.4}\n.note-ta:focus{border-color:var(--amber)}\n.note-ta:disabled{opacity:0.65;resize:none;cursor:default}\n.note-save{padding:5px 13px;background:var(--gd);border:none;border-radius:4px;\n  color:#fff;font-size:12px;cursor:pointer;font-family:\'DM Sans\',sans-serif;white-space:nowrap;align-self:flex-end;font-weight:500}\n.note-save:hover{background:var(--gm)}\n\n/* ── KPI active toggle ── */\n.kpi-active-badge{display:inline-flex;align-items:center;justify-content:center;\n  width:18px;height:18px;border-radius:4px;border:2px solid var(--gd);\n  background:#fff;font-size:11px;font-weight:700;color:#fff;cursor:pointer;transition:all 0.15s;flex-shrink:0}\n.kpi-active-badge.on{background:var(--gd)}\n.kpi-active-badge:hover{opacity:0.8}\n\n/* ── Toast ── */\n.toast{position:fixed;bottom:20px;right:20px;background:#1a2e1a;border:1px solid var(--gm);\n  border-radius:8px;padding:10px 16px;font-size:13px;color:#fff;z-index:999;\n  transform:translateY(16px);opacity:0;transition:all 0.25s;pointer-events:none}\n.toast.show{transform:translateY(0);opacity:1}\n.toast.ok{border-color:#4ade80;color:#4ade80}\n.toast.err{border-color:#f87171;color:#f87171}\n\n@media(max-width:600px){\n  .brand-sub,.brand-name{font-size:13px}\n  .tab{padding:5px 10px;font-size:12px}\n  .main{padding:14px 8px}\n}\n</style>\n</head>\n<body>\n\n<div class="topbar">\n  <div class="brand">\n    <div class="brand-icon">⛳</div>\n    <div>\n      <div class="brand-name">RMGC Agronomy</div>\n      <div class="brand-sub">Royal Malta Golf Club · 2026</div>\n    </div>\n  </div>\n  <div class="tabs">\n    <button class="tab active" onclick="showPage(\'schedule\',this)">📋 Schedule</button>\n    <button class="tab" onclick="showPage(\'kpis\',this)">🎯 KPIs</button>\n  </div>\n  <div class="topbar-right">\n    <span class="sync-dot" id="syncDot" title="Sync status"></span>\n    <div class="user-badge"><span>{{ username }}</span> · {{ role }}</div>\n    <a href="/logout" class="logout-btn">logout</a>\n  </div>\n</div>\n\n<div class="main">\n\n  <!-- ══ SCHEDULE PAGE ══ -->\n  <div class="page active" id="page-schedule">\n    <div class="sec-header">\n      <div class="sec-title">Annual Maintenance Schedule 2026</div>\n      <div class="sec-stats">Done: <strong id="sch-done">0</strong> / <strong id="sch-total">0</strong> &nbsp;·&nbsp; <strong id="sch-pct">0%</strong></div>\n    </div>\n    <div class="prog-wrap">\n      <div class="prog-track"><div class="prog-fill" id="sch-bar" style="width:0%"></div></div>\n    </div>\n    <div class="gantt-outer">\n      <table class="gantt-table">\n        <thead><tr>\n          <th class="name-col">Operation / Treatment</th>\n          <th>Jan</th><th>Feb</th><th>Mar</th><th>Apr</th><th>May</th><th>Jun</th>\n          <th>Jul</th><th>Aug</th><th>Sep</th><th>Oct</th><th>Nov</th><th>Dec</th>\n          <th style="min-width:48px">Done</th>\n        </tr></thead>\n        <tbody id="sch-body"></tbody>\n      </table>\n    </div>\n  </div>\n\n  <!-- ══ KPIs PAGE ══ -->\n  <div class="page" id="page-kpis">\n    <div class="sec-header">\n      <div class="sec-title">KPI Schedule 2026</div>\n      <div class="sec-stats">Done: <strong id="kpi-done">0</strong> / <strong id="kpi-total">0</strong> &nbsp;·&nbsp; <strong id="kpi-pct">0%</strong> &nbsp;·&nbsp; <strong id="kpi-active-count">0</strong> KPIs active</div>\n    </div>\n    <div class="prog-wrap">\n      <div class="prog-track"><div class="prog-fill" id="kpi-bar" style="width:0%"></div></div>\n    </div>\n    <div class="gantt-outer">\n      <table class="gantt-table">\n        <thead><tr>\n          <th class="name-col" style="min-width:240px">KPI / Goal</th>\n          <th style="min-width:32px;font-size:10px" title="Active for 2026">2026</th>\n          <th>Jan</th><th>Feb</th><th>Mar</th><th>Apr</th><th>May</th><th>Jun</th>\n          <th>Jul</th><th>Aug</th><th>Sep</th><th>Oct</th><th>Nov</th><th>Dec</th>\n          <th style="min-width:48px">Done</th>\n        </tr></thead>\n        <tbody id="kpi-body"></tbody>\n      </table>\n    </div>\n  </div>\n\n</div>\n<div class="toast" id="toast"></div>\n\n<script>\nconst ROLE = \'{{ role }}\';\nconst CAN_EDIT = ROLE === \'edit\';\nconst MO = [\'Jan\',\'Feb\',\'Mar\',\'Apr\',\'May\',\'Jun\',\'Jul\',\'Aug\',\'Sep\',\'Oct\',\'Nov\',\'Dec\'];\n\n// ══ SCHEDULE DATA (exact from v27) ══\nconst SCHEDULE_DATA = [\n  {op:"Greens – Mini-tine aeration",       cat:"AERATION & TOPDRESSING", months:["Jan","Feb","Mar","Apr","Jun","Jul","Aug","Oct","Nov","Dec"]},\n  {op:"Greens – Core aeration + topdress", cat:"AERATION & TOPDRESSING", months:["May","Sep"]},\n  {op:"Greens – Light topdress",           cat:"AERATION & TOPDRESSING", months:["Apr","Jun","Sep","Oct","Nov"]},\n  {op:"Aprons – Core aeration + topdress", cat:"AERATION & TOPDRESSING", months:["Apr","Jun","Aug"]},\n  {op:"Tees – Core aeration + topdress",   cat:"AERATION & TOPDRESSING", months:["Apr"]},\n  {op:"Tees – Overseeding (80 g/m²)",      cat:"AERATION & TOPDRESSING", months:["Nov","Dec"]},\n  {op:"Fairways & Rough – Solid tine",     cat:"AERATION & TOPDRESSING", months:["Apr"]},\n  {op:"Fairways – Verticutt",              cat:"AERATION & TOPDRESSING", months:["May","Jun","Jul"]},\n  {op:"Greens – Foliar (every 2–3 wks)",   cat:"NUTRITION",              months:["Jan","Feb","Mar","May","Jun","Jul","Aug","Oct","Nov","Dec"]},\n  {op:"Greens – Granular",                 cat:"NUTRITION",              months:["Apr","Jun","Sep"]},\n  {op:"Tees & Surrounds – 12-12-17",       cat:"NUTRITION",              months:["Mar","May","Jul","Sep"]},\n  {op:"Fairways & Rough – Urea 46-0-0",    cat:"NUTRITION",              months:["Mar","Sep"]},\n  {op:"Revolution – 20 L/ha (greens)",     cat:"WETTING AGENTS",         months:["Mar","Apr","May","Jun","Jul","Aug","Sep"]},\n  {op:"Fungicide – Greens (monthly)",      cat:"PLANT PROTECTION",       months:["May","Jun","Jul","Aug","Sep"]},\n  {op:"Fungicide – Fairways/Rough",        cat:"PLANT PROTECTION",       months:["Feb","Mar","Apr"]},\n  {op:"Herbicide – Kerb Flo (PRE-em)",     cat:"PLANT PROTECTION",       months:["Mar","Aug","Dec"]},\n  {op:"Herbicide – Spot POST-emergent",    cat:"PLANT PROTECTION",       months:["May","Jul"]},\n  {op:"Insecticide – White grubs",         cat:"PLANT PROTECTION",       months:["May","Jul","Sep"]},\n  {op:"Insecticide – Greens (monthly)",    cat:"PLANT PROTECTION",       months:["May","Jun","Jul","Aug","Sep"]},\n  {op:"Palm trees – Insecticide",          cat:"PLANT PROTECTION",       months:["Feb","Apr","Jun","Aug","Oct","Dec"]},\n];\nconst SCH_CATS = {\n  "AERATION & TOPDRESSING":{bg:"#6abf8a",text:"#0d3320"},\n  "NUTRITION":             {bg:"#f5b942",text:"#5c3800"},\n  "WETTING AGENTS":        {bg:"#5aabdf",text:"#062a4e"},\n  "PLANT PROTECTION":      {bg:"#9b59b6",text:"#4a1060"},\n};\n\n// ══ KPI DATA (exact from v27) ══\nconst KPI_DATA = [\n  {id:1,  cat:"Green Surfaces",  title:"Green Surrounds – Turf Recovery",\n   kpi:"Reduce returfing frequency on problem greens by 50%", cost:"€10,140/yr",\n   months:["Jan","Feb","Mar","Apr","May","Jun","Jul","Aug","Sep","Oct","Nov","Dec"],\n   actions:["Mowing ≥3×/week on surrounds","Fix drainage (KPI 4)","Increase fertilization"]},\n  {id:2,  cat:"Green Surfaces",  title:"Kikuyu Encroachment on Greens",\n   kpi:"Zero Kikuyu encroachment on 9 greens", cost:"€4,536 + sod",\n   months:["May","Jun","Jul","Aug","Sep","Oct"],\n   actions:["Zoysia collar resodding Jun–Oct","Returf perimeters Jan–Dec","Remove stolons inside greens"]},\n  {id:3,  cat:"Green Surfaces",  title:"Pitch-mark Compliance",\n   kpi:"Reduce unrepaired pitch-marks by 50% by May 2026", cost:"€3,120/yr",\n   months:["Jan","Feb","Mar","Apr","May","Jun","Jul","Aug","Sep","Oct","Nov","Dec"],\n   actions:["5 min pitch-mark repair before every mow on all greens"]},\n  {id:4,  cat:"Course Condition",  title:"Bare & Boggy Areas (Drainage)",\n   kpi:"Resolve surface water in 5 key boggy areas", cost:"€3,600 labour",\n   months:["Mar","Apr","May","Jun","Jul","Aug","Sep","Oct"],\n   actions:["Right G8","Left G9","Front-left G10","Right G4","Front G17"]},\n  {id:5,  cat:"Course Condition",  title:"Weed Free – Rough & Fairways",\n   kpi:"3 pre-emergence herbicide applications per year", cost:"€5,500/yr",\n   months:["Apr","Aug","Dec"],\n   actions:["1st pre-emergence Apr","2nd pre-emergence Aug","3rd pre-emergence Dec","Spot post-em as needed"]},\n  {id:6,  cat:"Course Condition",  title:"High-Wear Recovery Program",\n   kpi:"75% recovery in 5 identified high-wear areas", cost:"€10,200/yr",\n   months:["Apr","May","Jun","Sep","Oct"],\n   actions:["Aeration wall-to-wall ×2 (May & Sep)","Fertilization Apr, Jun, Oct","Re-turfing worn areas"]},\n  {id:7,  cat:"Green Surfaces",  title:"Apron & Approach Quality",\n   kpi:"80% of greens with firm shaped aprons by Autumn", cost:"€7,250/yr",\n   months:["Jan","Feb","Mar","Apr","May","Jun","Jul","Aug","Sep","Oct","Nov","Dec"],\n   actions:["Mowing ≥3×/week on aprons","Topdressing & fertilization Apr, Jun, Aug, Oct"]},\n  {id:8,  cat:"Playability",  title:"Tee Leveling Plan",\n   kpi:"Complete leveling of 3 worst tees (7, 9, 18)", cost:"€3,600 labour",\n   months:["Mar","Apr","May","Jun","Jul","Aug","Sep","Oct"],\n   actions:["Tee 7 – sod out, level, resod","Tee 9 – sod out, level, resod","Tee 18 – sod out, level, resod"]},\n  {id:9,  cat:"Playability",  title:"Rough Playability",\n   kpi:"Reduce rough complaints by 50% over summer 2026", cost:"€10,640+",\n   months:["Mar","Apr","May","Jun","Jul","Aug","Sep","Oct","Nov"],\n   actions:["Growth regulators 8 applications","Mowing 2×/week in rough","Robots for holes 8–13 (option)"]},\n  {id:10,  cat:"Course Condition", title:"Bunker Consistency",\n   kpi:"75% of bunkers meet presentation & sand depth standards", cost:"€3,500 labour",\n   months:["Jan","Feb","Mar","Apr","May","Jun","Jul","Aug","Sep","Oct","Nov","Dec"],\n   actions:["Increase depth adjustments from 3 to 12×/year"]},\n  {id:11,  cat:"Course Condition", title:"Greens Speed & Consistency",\n   kpi:"Stimp 8.5–9.5 ft, <0.5 ft variation across all greens", cost:"€13,800/yr",\n   months:["Mar","Apr","May","Jun","Jul","Aug","Sep","Oct"],\n   actions:["Bi-monthly aeration","Weekly rolling","Topdressing with sand"]},\n  {id:12,  cat:"Infrastructure", title:"Entrance Pathway & 1st Tee",\n   kpi:"Complete upgrade of 1st tee entry area by April 2026", cost:"€11,800+",\n   months:["Jan","Feb","Mar","Apr","May","Jun","Jul","Aug","Sep","Oct","Nov","Dec"],\n   actions:["Daily mowing (robot)","Daily pathway cleaning","Clear tree shade","Interlock buggy exit"]},\n  {id:13,  cat:"Infrastructure", title:"Pump Station Upgrade",\n   kpi:"Reduce pump station breakdowns", cost:"€34,200",\n   months:["Mar","Apr","May","Jun","Jul","Aug","Sep","Oct"],\n   actions:["Renew 3 pumps (€11,000 each)","Annual service contract €1,200/yr"]},\n  {id:14,  cat:"Infrastructure", title:"Water Hazards Development",\n   kpi:"TBD – plans to be confirmed", cost:"TBD",\n   months:[],\n   actions:["Plans to be confirmed"]},\n];\n\nconst KPI_CATS = {\n  "Green Surfaces":      {bg:"#6abf8a", text:"#0d3320"},\n  "Course Condition":    {bg:"#f5b942", text:"#5c3800"},\n  "Playability":         {bg:"#5aabdf", text:"#062a4e"},\n  "Infrastructure":      {bg:"#16a085", text:"#0a3d2e"},\n};\n\n// ══ State ══\nlet ticks = {}, notes = {}, kpiActive = KPI_DATA.map(k=>k.id);\nlet openNoteKey = null;\n\n// ══ Sync ══\nconst syncDot = document.getElementById(\'syncDot\');\nfunction setSyncState(s){syncDot.className=\'sync-dot\'+(s===\'synced\'?\' synced\':s===\'syncing\'?\' syncing\':\'\')}\n\nasync function loadFromServer(){\n  setSyncState(\'syncing\');\n  try{\n    const [tr,nr] = await Promise.all([\n      fetch(\'/api/ticks\').then(r=>r.json()),\n      fetch(\'/api/notes\').then(r=>r.json()),\n    ]);\n    ticks = tr.ticks||{};\n    notes = nr||{};\n    if(Array.isArray(tr.kpiActive)) kpiActive = tr.kpiActive;\n    setSyncState(\'synced\');\n  }catch(e){setSyncState(\'\');showToast(\'Could not load data\',\'err\')}\n}\nasync function saveTicks(){\n  if(!CAN_EDIT) return;\n  setSyncState(\'syncing\');\n  try{\n    await fetch(\'/api/ticks\',{method:\'POST\',headers:{\'Content-Type\':\'application/json\'},\n      body:JSON.stringify({ticks,kpiActive})});\n    setSyncState(\'synced\');\n  }catch(e){setSyncState(\'\');showToast(\'Save failed\',\'err\')}\n}\nasync function saveNotes(){\n  if(!CAN_EDIT) return;\n  setSyncState(\'syncing\');\n  try{\n    await fetch(\'/api/notes\',{method:\'POST\',headers:{\'Content-Type\':\'application/json\'},body:JSON.stringify(notes)});\n    setSyncState(\'synced\');\n  }catch(e){setSyncState(\'\');showToast(\'Note save failed\',\'err\')}\n}\n\n// ══ Toast ══\nlet toastT;\nfunction showToast(msg,type=\'\'){\n  const t=document.getElementById(\'toast\');\n  t.textContent=msg;t.className=\'toast show \'+(type||\'\');\n  clearTimeout(toastT);toastT=setTimeout(()=>t.className=\'toast\',2500);\n}\n\n// ══ Page switch ══\nfunction showPage(id,btn){\n  document.querySelectorAll(\'.page\').forEach(p=>p.classList.remove(\'active\'));\n  document.querySelectorAll(\'.tab\').forEach(b=>b.classList.remove(\'active\'));\n  document.getElementById(\'page-\'+id).classList.add(\'active\');\n  btn.classList.add(\'active\');\n}\n\n// ══ Build tick cell ══\nfunction buildCell(type, rowKey, mStr, active){\n  const td = document.createElement(\'td\');\n  td.className = \'month-td\' + (active ? \'\' : \' inactive\');\n  if(!active) return td;\n  const key = `${type}:${rowKey}:${mStr}`;\n  td.dataset.key = key;\n\n  const wrap = document.createElement(\'div\');\n  wrap.className = \'tick-wrap\';\n  const btn = document.createElement(\'button\');\n  btn.className = \'tick-btn\' + (ticks[key]?\' ticked\':\'\');\n  btn.disabled = !CAN_EDIT;\n  btn.title = ticks[key]?\'Mark undone\':\'Mark done\';\n  if(CAN_EDIT) btn.addEventListener(\'click\',()=>toggleTick(key,btn));\n\n  const dot = document.createElement(\'div\');\n  dot.className = \'note-dot\' + ((notes[key]&&notes[key].trim())?\' vis\':\'\');\n  dot.dataset.noteDot = key;\n  dot.title = \'Note\';\n  dot.addEventListener(\'click\',e=>{e.stopPropagation();toggleNote(key,td,mStr);});\n\n  wrap.appendChild(btn); wrap.appendChild(dot);\n  td.appendChild(wrap);\n  return td;\n}\n\n// ══ Note drawer ══\nfunction toggleNote(key, anchorTd, mStr){\n  if(openNoteKey && openNoteKey!==key){\n    const old=document.querySelector(`.note-row[data-note-key="${openNoteKey}"]`);\n    if(old) old.classList.remove(\'open\');\n  }\n  const existing=document.querySelector(`.note-row[data-note-key="${key}"]`);\n  if(existing){existing.classList.toggle(\'open\');openNoteKey=existing.classList.contains(\'open\')?key:null;return;}\n\n  const parentRow=anchorTd.closest(\'tr\');\n  const colCount=parentRow.cells.length;\n  const noteRow=document.createElement(\'tr\');\n  noteRow.className=\'note-row open\';\n  noteRow.dataset.noteKey=key;\n  const noteTd=document.createElement(\'td\');\n  noteTd.colSpan=colCount;\n  const inner=document.createElement(\'div\');\n  inner.className=\'note-inner\';\n  const label=document.createElement(\'div\');\n  label.className=\'note-label\';\n  label.textContent=\'📝 Note — \'+mStr;\n  const ta=document.createElement(\'textarea\');\n  ta.className=\'note-ta\';\n  ta.placeholder=\'Add a note for \'+mStr+\'…\';\n  ta.value=notes[key]||\'\';\n  ta.disabled=!CAN_EDIT;\n  inner.appendChild(label);\n  inner.appendChild(ta);\n  if(CAN_EDIT){\n    const saveBtn=document.createElement(\'button\');\n    saveBtn.className=\'note-save\';\n    saveBtn.textContent=\'Save note\';\n    saveBtn.addEventListener(\'click\',()=>{\n      const val=ta.value.trim();\n      if(val) notes[key]=val; else delete notes[key];\n      const dot=document.querySelector(`[data-note-dot="${key}"]`);\n      if(dot) dot.className=\'note-dot\'+(val?\' vis\':\'\');\n      saveNotes();\n      showToast(\'Note saved\',\'ok\');\n    });\n    inner.appendChild(saveBtn);\n  }\n  noteTd.appendChild(inner);\n  noteRow.appendChild(noteTd);\n  parentRow.insertAdjacentElement(\'afterend\',noteRow);\n  openNoteKey=key;\n}\n\nfunction toggleTick(key,btn){\n  if(ticks[key]) delete ticks[key]; else ticks[key]=true;\n  btn.className=\'tick-btn\'+(ticks[key]?\' ticked\':\'\');\n  saveTicks(); updateStats();\n}\n\n// ══ Build Schedule ══\nfunction buildSchedule(){\n  const tbody=document.getElementById(\'sch-body\');\n  tbody.innerHTML=\'\';\n  let lastCat=\'\';\n  SCHEDULE_DATA.forEach((s,i)=>{\n    if(s.cat!==lastCat){\n      lastCat=s.cat;\n      const cc=SCH_CATS[s.cat]||{bg:\'#eee\',text:\'#333\'};\n      const sep=document.createElement(\'tr\');\n      sep.className=\'cat-sep\';\n      const sepTd=document.createElement(\'td\');\n      sepTd.colSpan=14;\n      sepTd.style.background=cc.bg;\n      sepTd.style.color=cc.text;\n      sepTd.textContent=s.cat;\n      sep.appendChild(sepTd);\n      tbody.appendChild(sep);\n    }\n    const cc=SCH_CATS[s.cat]||{bg:\'#eee\'};\n    const tr=document.createElement(\'tr\');\n    tr.className=\'data-row\';\n    const nameTd=document.createElement(\'td\');\n    nameTd.className=\'name-td\';\n    nameTd.textContent=s.op;\n    tr.appendChild(nameTd);\n    let done=0;\n    MO.forEach(m=>{\n      const active=s.months.includes(m);\n      const td=buildCell(\'sch\',i,m,true);\n      if(ticks[`sch:${i}:${m}`]) done++;\n      td.style.background=active ? cc.bg : \'#fff\';\n      tr.appendChild(td);\n    });\n    // done counter\n    const doneTd=document.createElement(\'td\');\n    doneTd.style.cssText=\'text-align:center;font-size:11.5px;font-weight:700;padding:4px 6px;color:var(--gd);border-left:1px solid var(--border)\';\n    doneTd.id=\'sch-row-done-\'+i;\n    doneTd.textContent=done+\'/\'+s.months.length;\n    tr.appendChild(doneTd);\n    tbody.appendChild(tr);\n  });\n}\n\n// ══ Build KPIs ══\nfunction buildKPIs(){\n  const tbody=document.getElementById(\'kpi-body\');\n  tbody.innerHTML=\'\';\n  let lastCat=\'\';\n  KPI_DATA.forEach((k)=>{\n    const isActive=kpiActive.includes(k.id);\n    const cc=KPI_CATS[k.cat]||{bg:\'#d4ecd4\',text:\'#1a4731\'};\n\n    // Category separator row (same as schedule)\n    if(k.cat && k.cat!==lastCat){\n      lastCat=k.cat;\n      const sep=document.createElement(\'tr\');\n      sep.className=\'cat-sep\';\n      const sepTd=document.createElement(\'td\');\n      sepTd.colSpan=15;\n      sepTd.style.background=cc.bg;\n      sepTd.style.color=cc.text;\n      sepTd.textContent=k.cat;\n      sep.appendChild(sepTd);\n      tbody.appendChild(sep);\n    }\n\n    const tr=document.createElement(\'tr\');\n    tr.className=\'data-row\';\n    tr.style.opacity=isActive?\'1\':\'0.6\';\n\n    const nameTd=document.createElement(\'td\');\n    nameTd.className=\'name-td\';\n    nameTd.style.maxWidth=\'240px\';\n    nameTd.innerHTML=`<span class="kn">${k.id}.</span><strong>${k.title}</strong><br><span style="font-size:10px;color:var(--muted)">${k.kpi}</span>`;\n    tr.appendChild(nameTd);\n\n    // active toggle\n    const activeTd=document.createElement(\'td\');\n    activeTd.style.cssText=\'text-align:center;padding:4px;border-right:1px solid var(--border)\';\n    const badge=document.createElement(\'div\');\n    badge.className=\'kpi-active-badge\'+(isActive?\' on\':\'\');\n    badge.title=\'Toggle 2026 active\';\n    badge.textContent=isActive?\'✓\':\'\';\n    if(CAN_EDIT) badge.addEventListener(\'click\',()=>toggleKPIActive(k.id));\n    activeTd.appendChild(badge);\n    tr.appendChild(activeTd);\n\n    let done=0;\n    MO.forEach(m=>{\n      const active=k.months.includes(m);\n      const td=buildCell(\'kpi\',k.id,m,true);\n      if(ticks[`kpi:${k.id}:${m}`] && isActive) done++;\n      td.style.background = active && isActive ? cc.bg : \'#fff\';\n      tr.appendChild(td);\n    });\n\n    const doneTd=document.createElement(\'td\');\n    doneTd.style.cssText=\'text-align:center;font-size:11.5px;font-weight:700;padding:4px 6px;color:var(--gd);border-left:1px solid var(--border)\';\n    doneTd.id=\'kpi-row-done-\'+k.id;\n    doneTd.textContent=k.months.length>0?(done+\'/\'+k.months.length):\'—\';\n    tr.appendChild(doneTd);\n    tbody.appendChild(tr);\n  });\n}\n\nfunction toggleKPIActive(id){\n  if(!CAN_EDIT) return;\n  if(kpiActive.includes(id)) kpiActive=kpiActive.filter(x=>x!==id);\n  else kpiActive.push(id);\n  buildKPIs(); updateStats(); saveTicks();\n}\n\n// ══ Apply state to existing DOM ══\nfunction applyState(){\n  document.querySelectorAll(\'.tick-btn\').forEach(btn=>{\n    const td=btn.closest(\'[data-key]\');\n    if(!td) return;\n    btn.className=\'tick-btn\'+(ticks[td.dataset.key]?\' ticked\':\'\');\n  });\n  document.querySelectorAll(\'[data-note-dot]\').forEach(dot=>{\n    const key=dot.dataset.noteDot;\n    dot.className=\'note-dot\'+((notes[key]&&notes[key].trim())?\' vis\':\'\');\n  });\n  updateStats();\n}\n\n// ══ Stats ══\nfunction updateStats(){\n  let sT=0,sD=0,kT=0,kD=0;\n  SCHEDULE_DATA.forEach((s,i)=>{\n    s.months.forEach(m=>{sT++;if(ticks[`sch:${i}:${m}`])sD++;});\n    const rowDone=s.months.filter(m=>ticks[`sch:${i}:${m}`]).length;\n    const el=document.getElementById(\'sch-row-done-\'+i);\n    if(el) el.textContent=rowDone+\'/\'+s.months.length;\n  });\n  KPI_DATA.forEach(k=>{\n    if(!kpiActive.includes(k.id)) return;\n    k.months.forEach(m=>{kT++;if(ticks[`kpi:${k.id}:${m}`])kD++;});\n    const rowDone=MO.filter(m=>ticks[`kpi:${k.id}:${m}`]).length;\n    const el=document.getElementById(\'kpi-row-done-\'+k.id);\n    if(el) el.textContent=k.months.length>0?(rowDone+\'/\'+k.months.length):\'—\';\n  });\n  document.getElementById(\'sch-done\').textContent=sD;\n  document.getElementById(\'sch-total\').textContent=sT;\n  const sp=sT?Math.round(sD/sT*100):0;\n  document.getElementById(\'sch-pct\').textContent=sp+\'%\';\n  document.getElementById(\'sch-bar\').style.width=sp+\'%\';\n  document.getElementById(\'kpi-done\').textContent=kD;\n  document.getElementById(\'kpi-total\').textContent=kT;\n  const kp=kT?Math.round(kD/kT*100):0;\n  document.getElementById(\'kpi-pct\').textContent=kp+\'%\';\n  document.getElementById(\'kpi-bar\').style.width=kp+\'%\';\n  document.getElementById(\'kpi-active-count\').textContent=kpiActive.length;\n}\n\n// ══ Poll every 30s ══\nasync function poll(){\n  try{\n    const [tr,nr]=await Promise.all([fetch(\'/api/ticks\').then(r=>r.json()),fetch(\'/api/notes\').then(r=>r.json())]);\n    ticks=tr.ticks||{}; notes=nr||{};\n    if(Array.isArray(tr.kpiActive)) kpiActive=tr.kpiActive;\n    buildKPIs(); applyState();\n    setSyncState(\'synced\');\n  }catch(e){}\n}\n\n// ══ Init ══\n(async()=>{\n  buildSchedule();\n  buildKPIs();\n  await loadFromServer();\n  buildKPIs();\n  applyState();\n  setInterval(poll,30000);\n})();\n</script>\n</body>\n</html>'

app = Flask(__name__)
app.secret_key = 'rmgc-schedule-secret-2026'
app.jinja_loader = DictLoader({'login.html': LOGIN_HTML, 'index.html': INDEX_HTML})

USERS = {
    'greens':   {'password': 'LB2026',      'role': 'edit'},
    'admin':    {'password': 'rmgc2026',    'role': 'read'},
    'gm@royalmaltagolfclub.com': {'password': 'MD2026', 'role': 'read'},
    'chairman': {'password': '3putt2026',   'role': 'read'},
    'deputy':   {'password': 'JP2026',      'role': 'read'},
}

SUPABASE_URL = os.environ.get('SUPABASE_URL', '')
SUPABASE_KEY = os.environ.get('SUPABASE_KEY', '')

def sb_headers():
    return {'apikey': SUPABASE_KEY,'Authorization': f'Bearer {SUPABASE_KEY}',
             'Content-Type': 'application/json','Prefer': 'return=representation'}

def sb_get(key):
    if not SUPABASE_URL: return None
    try:
        r = req.get(f'{SUPABASE_URL}/rest/v1/rmgc_data?id=eq.{key}&select=payload', headers=sb_headers(), timeout=5)
        data = r.json()
        if data: return data[0]['payload']
    except: pass
    return None

def sb_set(key, payload):
    if not SUPABASE_URL: return False
    try:
        r = req.post(f'{SUPABASE_URL}/rest/v1/rmgc_data',
            headers={**sb_headers(), 'Prefer': 'resolution=merge-duplicates,return=representation'},
            json={'id': key, 'payload': payload}, timeout=5)
        return r.status_code in (200, 201)
    except: return False

@app.route('/')
def index():
    if 'user' not in session: return redirect(url_for('login'))
    return render_template('index.html', username=session['user'], role=session['role'])

@app.route('/login', methods=['GET', 'POST'])
def login():
    error = ''
    if request.method == 'POST':
        u = request.form.get('username', '').strip().lower()
        p = request.form.get('password', '').strip()
        if u in USERS and USERS[u]['password'] == p:
            session['user'] = u
            session['role'] = USERS[u]['role']
            return redirect(url_for('index'))
        error = 'Invalid username or password'
    return render_template('login.html', error=error)

@app.route('/logout')
def logout():
    session.clear()
    return redirect(url_for('login'))

@app.route('/api/ticks', methods=['GET'])
def get_ticks():
    if 'user' not in session: return jsonify({'error': 'unauthorized'}), 401
    data = sb_get('ticks2') or {'ticks': {}, 'kpiActive': list(range(1,15))}
    return jsonify(data)

@app.route('/api/ticks', methods=['POST'])
def save_ticks():
    if 'user' not in session: return jsonify({'error': 'unauthorized'}), 401
    if session.get('role') != 'edit': return jsonify({'error': 'read-only'}), 403
    body = request.get_json()
    sb_set('ticks2', body)
    return jsonify({'ok': True})

@app.route('/api/notes', methods=['GET'])
def get_notes():
    if 'user' not in session: return jsonify({'error': 'unauthorized'}), 401
    return jsonify(sb_get('notes2') or {})

@app.route('/api/notes', methods=['POST'])
def save_notes():
    if 'user' not in session: return jsonify({'error': 'unauthorized'}), 401
    if session.get('role') != 'edit': return jsonify({'error': 'read-only'}), 403
    sb_set('notes2', request.get_json())
    return jsonify({'ok': True})

@app.route('/api/debug')
def debug():
    ok = False; msg = 'No Supabase configured'
    if SUPABASE_URL:
        try:
            r = req.get(f'{SUPABASE_URL}/rest/v1/rmgc_data?select=id&limit=1', headers=sb_headers(), timeout=5)
            ok = r.status_code == 200
            msg = f'Connected — {len(r.json())} row(s)' if ok else r.text
        except Exception as e: msg = str(e)
    return jsonify({'supabase_ok': ok, 'supabase_msg': msg})

if __name__ == '__main__':
    app.run(debug=True)
